// The Crystal module format and the allowlist check that guards it.
//
// Crystal code runs inside the server process with no sandbox, so the module
// must be exactly this shape, and the shaping function may use only a small,
// side-effect-free subset of JavaScript:
//
//   // Generated by `slime crystallize` ...
//   export const sql = "SELECT ...";
//   export const params = ["limit"];
//   export function shape(rows, input) { ... }      // or: export const shape = null;
//
// The same check runs when `crystallize` writes a module and again when the
// server loads one, so a hand-edited file that re-pins its hash is still refused.
import { parse, type Node } from 'acorn';
import { fullAncestor } from 'acorn-walk';

export interface CrystalCode {
  sql: string;
  params: string[];
  /** Source of `function shape(rows, input) { ... }`, or null when SQL rows are the output. */
  shape: string | null;
}

export class CrystalCodeError extends Error {}

const HEADER =
  '// Generated by `slime crystallize`. Do not edit: crystal/manifest.json pins this\n' +
  "// file's hash, and the server refuses a file that doesn't match it.\n";

export function renderModule(code: CrystalCode): string {
  // Trailing whitespace is stripped so the repo's pre-commit hooks never rewrite
  // the file (which would break its pinned hash).
  const shape = code.shape
    ? `export ${code.shape.trim().split('\n').map((l) => l.trimEnd()).join('\n')}`
    : 'export const shape = null;';
  return `${HEADER}export const sql = ${JSON.stringify(code.sql)};\nexport const params = ${JSON.stringify(code.params)};\n${shape}\n`;
}

/** Parses a module, checks its structure and its shaping function, and returns its code. */
export function parseModule(source: string): CrystalCode {
  let program: any;
  try {
    program = parse(source, { ecmaVersion: 2022, sourceType: 'module' });
  } catch (err) {
    throw new CrystalCodeError(`not valid JavaScript: ${(err as Error).message}`);
  }
  const body = program.body;
  if (body.length !== 3) throw new CrystalCodeError('module must contain exactly sql, params and shape exports');

  const sql = constExport(body[0], 'sql');
  if (sql?.type !== 'Literal' || typeof sql.value !== 'string') throw new CrystalCodeError('`sql` must be a string literal');

  const params = constExport(body[1], 'params');
  if (params?.type !== 'ArrayExpression' || !params.elements.every((e: any) => e?.type === 'Literal' && typeof e.value === 'string')) {
    throw new CrystalCodeError('`params` must be an array of string literals');
  }

  const third = body[2];
  let shape: string | null = null;
  const shapeNull = constExport(third, 'shape');
  if (shapeNull) {
    if (!(shapeNull.type === 'Literal' && shapeNull.value === null)) throw new CrystalCodeError('`shape` must be a function or null');
  } else if (third.type === 'ExportNamedDeclaration' && third.declaration?.type === 'FunctionDeclaration' && third.declaration.id?.name === 'shape') {
    checkShapeFunction(third.declaration);
    shape = source.slice(third.declaration.start, third.declaration.end);
  } else {
    throw new CrystalCodeError('third export must be `export function shape(rows, input)` or `export const shape = null`');
  }
  return { sql: sql.value, params: params.elements.map((e: any) => e.value), shape };
}

/** Checks a standalone `function shape(rows, input) {...}` source (used before rendering). */
export function checkShapeSource(source: string): void {
  let program: any;
  try {
    program = parse(source, { ecmaVersion: 2022, sourceType: 'module' });
  } catch (err) {
    throw new CrystalCodeError(`not valid JavaScript: ${(err as Error).message}`);
  }
  const fn = program.body[0];
  if (program.body.length !== 1 || fn.type !== 'FunctionDeclaration' || fn.id?.name !== 'shape') {
    throw new CrystalCodeError('must be a single `function shape(rows, input) { ... }`');
  }
  checkShapeFunction(fn);
}

function constExport(node: any, name: string): any {
  if (node.type !== 'ExportNamedDeclaration' || node.declaration?.type !== 'VariableDeclaration') return undefined;
  const decl = node.declaration;
  if (decl.kind !== 'const' || decl.declarations.length !== 1) return undefined;
  const d = decl.declarations[0];
  return d.id.type === 'Identifier' && d.id.name === name ? d.init : undefined;
}

// ---------------------------------------------------------------------------
// The allowlist.

// Globals the shaping function may use, and the static members it may call on
// each (`*` = any member except the banned names below).
const GLOBALS: Record<string, Set<string> | '*'> = {
  Math: '*',
  Object: new Set(['keys', 'values', 'entries', 'fromEntries']),
  Array: new Set(['isArray', 'from', 'of']),
  JSON: new Set(['stringify', 'parse']),
  Number: new Set(['isInteger', 'isFinite', 'isNaN', 'parseFloat', 'parseInt', 'MAX_SAFE_INTEGER', 'MIN_SAFE_INTEGER', 'EPSILON']),
  String: new Set(['fromCharCode']),
  Date: new Set(['UTC', 'parse']),
  Intl: new Set(['NumberFormat', 'DateTimeFormat', 'PluralRules', 'Collator', 'ListFormat', 'RelativeTimeFormat']),
  Boolean: new Set(),
  Map: new Set(),
  Set: new Set(),
  parseInt: new Set(),
  parseFloat: new Set(),
  isNaN: new Set(),
  isFinite: new Set(),
};
const VALUE_GLOBALS = new Set(['undefined', 'NaN', 'Infinity']);

// Property names that lead out of plain data: to constructors (and from there to
// `Function`, i.e. arbitrary code), prototypes, or global mutation.
const BANNED_PROPS = new Set([
  'constructor', 'prototype', '__proto__', '__defineGetter__', '__defineSetter__',
  '__lookupGetter__', '__lookupSetter__', 'defineProperty', 'defineProperties',
  'setPrototypeOf', 'getPrototypeOf', 'getOwnPropertyDescriptor', 'getOwnPropertyDescriptors',
  'caller', 'callee', 'arguments',
]);

const BANNED_NODES: Record<string, string> = {
  ThisExpression: '`this`',
  MetaProperty: '`new.target` / `import.meta`',
  ImportExpression: 'dynamic `import()`',
  AwaitExpression: '`await`',
  YieldExpression: 'generators',
  ClassDeclaration: 'classes',
  ClassExpression: 'classes',
  WithStatement: '`with`',
  DebuggerStatement: '`debugger`',
  WhileStatement: '`while` loops (use for...of or array methods)',
  DoWhileStatement: '`do...while` loops (use for...of or array methods)',
  ForStatement: '`for(;;)` loops (use for...of or array methods)',
  ForInStatement: '`for...in` (use Object.keys/entries)',
  LabeledStatement: 'labels',
};

function checkShapeFunction(fn: any): void {
  if (fn.async || fn.generator) throw new CrystalCodeError('shape must be a plain synchronous function');
  const declared = collectDeclaredNames(fn);
  const fail = (node: Node, what: string): never => {
    throw new CrystalCodeError(`${what} is not allowed in Crystal code (at offset ${node.start})`);
  };

  // Pass 1: forbidden constructs, reported by name. (The walker visits children
  // first, so without this pass a class would be reported as its unknown name.)
  fullAncestor(fn, (node: any) => {
    if (BANNED_NODES[node.type]) fail(node, BANNED_NODES[node.type]);
    if ((node.type === 'FunctionExpression' || node.type === 'ArrowFunctionExpression' || node.type === 'FunctionDeclaration') && (node.async || node.generator)) {
      fail(node, 'async functions and generators');
    }
  });

  // Pass 2: what the code reads and writes.
  fullAncestor(fn, (node: any, _state: unknown, ancestors: any[]) => {
    const parent = ancestors[ancestors.length - 2];

    if (node.type === 'MemberExpression') {
      if (node.computed) {
        // obj[key] with a variable key can reach `constructor` at run time, so only
        // literal numeric indexes and literal, non-banned string keys are allowed.
        const p = node.property;
        const literalOk = p.type === 'Literal' && (typeof p.value === 'number' || (typeof p.value === 'string' && !BANNED_PROPS.has(p.value)));
        if (!literalOk) fail(node, 'computed property access with a variable key (use a Map)');
      } else if (BANNED_PROPS.has(node.property.name)) {
        fail(node, `\`.${node.property.name}\``);
      }
      // Static members of globals are limited per global.
      if (node.object.type === 'Identifier' && !declared.has(node.object.name) && GLOBALS[node.object.name]) {
        const allowed = GLOBALS[node.object.name];
        const prop = node.computed ? String(node.property.value) : node.property.name;
        if (allowed !== '*' && !allowed.has(prop)) fail(node, `\`${node.object.name}.${prop}\``);
      }
      // No assigning to or deleting members of globals (host-wide mutation).
      if (isWriteTarget(node, parent) && rootIdentifier(node) && !declared.has(rootIdentifier(node)!)) {
        fail(node, 'changing a global');
      }
    }

    if (node.type === 'Identifier' && isReference(node, parent)) {
      const name = node.name;
      if (declared.has(name)) return;
      if (VALUE_GLOBALS.has(name)) return;
      if (GLOBALS[name]) {
        // A global may only be called / constructed or have an allowed member read;
        // never passed around as a value (e.g. Object.assign(Math, ...)).
        const called = (parent.type === 'CallExpression' || parent.type === 'NewExpression') && parent.callee === node;
        const memberRead = parent.type === 'MemberExpression' && parent.object === node;
        if (called || memberRead) return;
        fail(node, `using \`${name}\` as a value`);
      }
      fail(node, `\`${name}\``);
    }
  });
}

function isWriteTarget(node: any, parent: any): boolean {
  return (
    (parent?.type === 'AssignmentExpression' && parent.left === node) ||
    (parent?.type === 'UpdateExpression' && parent.argument === node) ||
    (parent?.type === 'UnaryExpression' && parent.operator === 'delete' && parent.argument === node)
  );
}

function rootIdentifier(node: any): string | null {
  let n = node;
  while (n.type === 'MemberExpression') n = n.object;
  return n.type === 'Identifier' ? n.name : null;
}

/** True when an Identifier node is read as a variable (not a property name or label). */
function isReference(node: any, parent: any): boolean {
  if (!parent) return true;
  if (parent.type === 'MemberExpression' && parent.property === node && !parent.computed) return false;
  // `{ a: 1 }` key is a name; `{ a }` shorthand is a reference to the variable `a`.
  if (parent.type === 'Property' && parent.key === node && !parent.computed && !parent.shorthand) return false;
  if (parent.type === 'MethodDefinition' && parent.key === node && !parent.computed) return false;
  if ((parent.type === 'BreakStatement' || parent.type === 'ContinueStatement') && parent.label === node) return false;
  return true;
}

/** Every name the function declares: parameters, variables, inner functions, catch params. */
function collectDeclaredNames(fn: any): Set<string> {
  const names = new Set<string>();
  const addPattern = (p: any) => {
    if (!p) return;
    if (p.type === 'Identifier') names.add(p.name);
    else if (p.type === 'ObjectPattern') p.properties.forEach((prop: any) => addPattern(prop.type === 'RestElement' ? prop.argument : prop.value));
    else if (p.type === 'ArrayPattern') p.elements.forEach(addPattern);
    else if (p.type === 'AssignmentPattern') addPattern(p.left);
    else if (p.type === 'RestElement') addPattern(p.argument);
  };
  fullAncestor(fn, (node: any) => {
    if (node.type === 'VariableDeclarator') addPattern(node.id);
    if (node.type === 'FunctionDeclaration' || node.type === 'FunctionExpression' || node.type === 'ArrowFunctionExpression') {
      if (node.id) names.add(node.id.name);
      node.params.forEach(addPattern);
    }
    if (node.type === 'CatchClause') addPattern(node.param);
  });
  return names;
}
